mapper.select:
SELECT t.*,
u.user_name,
u.avatar
FROM `industry_news_comment` t,
tb_user u
WHERE t.user_id = u.user_id

    and t.news_id = #{industryNewsComment.newsId}


      and t.status = #{industryNewsComment.status}


    and t.user_id = #{industryNewsComment.userId}

order by create_time desc
